t.script:
                (function () {
                    "use strict";

                    function clearElement(element) {
                        while (element.firstChild) {
                            element.removeChild(element.firstChild);
                        }
                    }

                    function createTextMessage(container, message, className) {
                        clearElement(container);

                        var element = document.createElement("p");
                        element.textContent = message;
                        element.className = className || "";
                        container.appendChild(element);
                    }

                    function showCalendarError(calendarElement, message) {
                        clearElement(calendarElement);

                        var errorBox = document.createElement("div");
                        errorBox.textContent = message;
                        errorBox.className = "lesson-calendar-error";

                        calendarElement.appendChild(errorBox);
                    }

                    function waitForFullCalendar(attempt) {
                        if (typeof FullCalendar !== "undefined") {
                            initLessonProgramBooking();
                            return;
                        }

                        if (attempt < 30) {
                            window.setTimeout(function () {
                                waitForFullCalendar(attempt + 1);
                            }, 200);
                            return;
                        }

                        var calendarElement =
                            document.getElementById("lesson-program-calendar");

                        var loadingElement =
                            document.getElementById("lesson-calendar-loading");

                        if (loadingElement) {
                            loadingElement.style.display = "none";
                        }

                        if (calendarElement) {
                            showCalendarError(
                                calendarElement,
                                "Calendar could not load. Please refresh the page."
                            );
                        }

                        console.error("FullCalendar did not load.");
                    }

                    function initLessonProgramBooking() {
                        var calendarElement =
                            document.getElementById("lesson-program-calendar");

                        var loadingElement =
                            document.getElementById("lesson-calendar-loading");

                        var programInput =
                            document.getElementById("lesson_program_id");

                        var sessionCountInput =
                            document.getElementById("session_count");

                        var selectedInput =
                            document.getElementById("selected_booking_ids");

                        var addToCartButton =
                            document.getElementById("lesson-program-add-to-cart");

                        var selectionInfo =
                            document.getElementById("selection-info");

                        var messageBox =
                            document.getElementById("lesson-program-message");

                        var calendarColumn =
                            document.getElementById("lesson-calendar-column");

                        var timesColumn =
                            document.getElementById("lesson-times-column");

                        var selectedDateLabel =
                            document.getElementById("selected-date-label");

                        var availableTimesContainer =
                            document.getElementById("available-times");

                        if (!calendarElement ||
                            !programInput ||
                            !sessionCountInput ||
                            !selectedInput ||
                            !addToCartButton ||
                            !selectionInfo ||
                            !messageBox ||
                            !calendarColumn ||
                            !timesColumn ||
                            !selectedDateLabel ||
                            !availableTimesContainer) {

                            console.error(
                                "One or more lesson-program elements are missing."
                            );
                            return;
                        }

                        var programId = programInput.value;

                        var sessionCount = parseInt(
                            sessionCountInput.value,
                            10
                        );

                        var selectedBookingIds = [];
                        var messageTimer = null;
                        var timesPanelHasOpened = false;

                        function showMessage(message, type) {
                            if (!type) {
                                type = "warning";
                            }

                            if (messageTimer) {
                                window.clearTimeout(messageTimer);
                            }

                            messageBox.className =
                                "alert alert-" + type;

                            messageBox.textContent = message;
                            messageBox.classList.remove("d-none");

                            messageTimer = window.setTimeout(function () {
                                messageBox.classList.add("d-none");
                            }, 4000);
                        }

                        function refreshButtonState() {
                            selectedInput.value =
                                JSON.stringify(selectedBookingIds);

                            var remaining =
                                sessionCount - selectedBookingIds.length;

                            if (remaining > 0) {
                                selectionInfo.textContent =
                                    "Please select " +
                                    remaining +
                                    " more lesson time(s).";

                                addToCartButton.disabled = true;
                                addToCartButton.classList.add("disabled");
                            } else {
                                selectionInfo.textContent =
                                    "You selected all " +
                                    sessionCount +
                                    " lesson time(s).";

                                addToCartButton.disabled = false;
                                addToCartButton.classList.remove("disabled");
                            }
                        }

                        function openAvailableTimesPanel(calendar) {
                            if (timesPanelHasOpened) {
                                return;
                            }

                            calendarColumn.classList.remove("col-12");
                            calendarColumn.classList.add("col-md-8");

                            timesColumn.style.display = "block";
                            timesPanelHasOpened = true;

                            window.setTimeout(function () {
                                calendar.updateSize();
                            }, 50);
                        }

                        function markSelectedDate(dayElement) {
                            var selectedDays = document.querySelectorAll(
                                ".fc-daygrid-day.selected-calendar-date"
                            );

                            var index;

                            for (index = 0; index < selectedDays.length; index++) {
                                selectedDays[index].classList.remove(
                                    "selected-calendar-date"
                                );
                            }

                            if (dayElement) {
                                dayElement.classList.add(
                                    "selected-calendar-date"
                                );
                            }
                        }

                        function formatSelectedDate(dateObject) {
                            return dateObject.toLocaleDateString(
                                undefined,
                                {
                                    weekday: "long",
                                    year: "numeric",
                                    month: "long",
                                    day: "numeric"
                                }
                            );
                        }

                        function createTimeButton(slot) {
                            var button = document.createElement("button");
                            var bookingId = parseInt(slot.booking_id, 10);

                            button.type = "button";
                            button.textContent = slot.time;
                            button.className =
                                "lesson-time-pill btn btn-outline-primary";

                            button.setAttribute(
                                "data-booking-id",
                                bookingId
                            );

                            if (selectedBookingIds.indexOf(bookingId) !== -1) {
                                button.classList.add("selected-slot");
                            }

                            button.addEventListener("click", function () {
                                var currentBookingId = parseInt(
                                    this.getAttribute("data-booking-id"),
                                    10
                                );

                                var selectedIndex =
                                    selectedBookingIds.indexOf(
                                        currentBookingId
                                    );

                                if (selectedIndex !== -1) {
                                    selectedBookingIds.splice(
                                        selectedIndex,
                                        1
                                    );

                                    this.classList.remove(
                                        "selected-slot"
                                    );
                                } else {
                                    if (selectedBookingIds.length >=
                                        sessionCount) {

                                        showMessage(
                                            "You can only select " +
                                            sessionCount +
                                            " lesson time(s).",
                                            "warning"
                                        );

                                        return;
                                    }

                                    selectedBookingIds.push(
                                        currentBookingId
                                    );

                                    this.classList.add(
                                        "selected-slot"
                                    );
                                }

                                refreshButtonState();
                            });

                            return button;
                        }

                        function loadAvailableTimes(dateString) {
                            clearElement(availableTimesContainer);

                            var loadingMessage =
                                document.createElement("p");

                            loadingMessage.className =
                                "text-muted mb-0";

                            loadingMessage.textContent =
                                "Loading available times...";

                            availableTimesContainer.appendChild(
                                loadingMessage
                            );

                            var url =
                                "/lesson_program/available_times" +
                                "?program_id=" +
                                encodeURIComponent(programId) +
                                "&date=" +
                                encodeURIComponent(dateString);

                            fetch(url, {
                                method: "GET",
                                credentials: "same-origin"
                            })
                            .then(function (response) {
                                if (!response.ok) {
                                    throw new Error(
                                        "HTTP error " + response.status
                                    );
                                }

                                return response.json();
                            })
                            .then(function (times) {
                                clearElement(
                                    availableTimesContainer
                                );

                                if (!times || !times.length) {
                                    availableTimesContainer.classList.remove(
                                        "lesson-times-grid"
                                    );

                                    createTextMessage(
                                        availableTimesContainer,
                                        "No available times for this date.",
                                        "text-muted mb-0"
                                    );

                                    return;
                                }

                                availableTimesContainer.classList.add(
                                    "lesson-times-grid"
                                );

                                var index;

                                for (index = 0; index < times.length; index++) {
                                    availableTimesContainer.appendChild(
                                        createTimeButton(times[index])
                                    );
                                }
                            })
                            .catch(function (error) {
                                console.error(
                                    "Error loading available times:",
                                    error
                                );

                                availableTimesContainer.classList.remove(
                                    "lesson-times-grid"
                                );

                                createTextMessage(
                                    availableTimesContainer,
                                    "Could not load available times.",
                                    "text-danger mb-0"
                                );
                            });
                        }

                        var calendar = new FullCalendar.Calendar(
                            calendarElement,
                            {
                                initialView: "dayGridMonth",
                                height: "auto",

                                headerToolbar: {
                                    left: "prev,next today",
                                    center: "title",
                                    right: "dayGridMonth,timeGridWeek"
                                },

                                validRange: {
                                    start: new Date()
                                        .toISOString()
                                        .split("T")[0]
                                },

                                events: function (
                                    fetchInfo,
                                    successCallback,
                                    failureCallback
                                ) {
                                    var url =
                                        "/lesson_program/available_dates" +
                                        "?program_id=" +
                                        encodeURIComponent(programId);

                                    fetch(url, {
                                        method: "GET",
                                        credentials: "same-origin"
                                    })
                                    .then(function (response) {
                                        if (!response.ok) {
                                            throw new Error(
                                                "HTTP error " +
                                                response.status
                                            );
                                        }

                                        return response.json();
                                    })
                                    .then(function (data) {
                                        var events = [];
                                        var dateKey;

                                        for (dateKey in data) {
                                            if (
                                                Object.prototype
                                                    .hasOwnProperty
                                                    .call(data, dateKey)
                                            ) {
                                                events.push({
                                                    title: "",
                                                    start: dateKey,
                                                    allDay: true,
                                                    display: "background",
                                                    classNames: [
                                                        "fc-available-date"
                                                    ]
                                                });
                                            }
                                        }

                                        successCallback(events);
                                    })
                                    .catch(function (error) {
                                        console.error(
                                            "Error loading calendar dates:",
                                            error
                                        );

                                        failureCallback(error);
                                    });
                                },

                                dateClick: function (info) {
                                    markSelectedDate(info.dayEl);

                                    selectedDateLabel.textContent =
                                        formatSelectedDate(info.date);

                                    openAvailableTimesPanel(calendar);

                                    loadAvailableTimes(info.dateStr);
                                }
                            }
                        );

                        try {
                            calendar.render();

                            if (loadingElement) {
                                loadingElement.style.display = "none";
                            }

                            window.setTimeout(function () {
                                calendar.updateSize();
                            }, 100);
                        } catch (error) {
                            console.error(
                                "Calendar rendering failed:",
                                error
                            );

                            if (loadingElement) {
                                loadingElement.style.display = "none";
                            }

                            showCalendarError(
                                calendarElement,
                                "Calendar could not be displayed."
                            );

                            return;
                        }

                        refreshButtonState();

                        addToCartButton.addEventListener(
                            "click",
                            function (event) {
                                event.preventDefault();

                                if (
                                    selectedBookingIds.length !==
                                    sessionCount
                                ) {
                                    showMessage(
                                        "Please select exactly " +
                                        sessionCount +
                                        " lesson time(s).",
                                        "warning"
                                    );

                                    return;
                                }

                                addToCartButton.disabled = true;
                                addToCartButton.classList.add(
                                    "disabled"
                                );

                                var formData = new FormData();

                                formData.append(
                                    "program_id",
                                    programId
                                );

                                formData.append(
                                    "selected_booking_ids",
                                    JSON.stringify(
                                        selectedBookingIds
                                    )
                                );

                                fetch(
                                    "/custom/update_lesson_program_order_line",
                                    {
                                        method: "POST",
                                        credentials: "same-origin",
                                        body: formData
                                    }
                                )
                                .then(function (response) {
                                    return response.json().then(
                                        function (data) {
                                            return {
                                                ok: response.ok,
                                                data: data
                                            };
                                        }
                                    );
                                })
                                .then(function (result) {
                                    if (
                                        result.ok &&
                                        result.data.success &&
                                        result.data.redirect
                                    ) {
                                        window.location.href =
                                            result.data.redirect;

                                        return;
                                    }

                                    showMessage(
                                        result.data.error ||
                                        "Could not add the lesson program to the cart.",
                                        "danger"
                                    );

                                    refreshButtonState();
                                })
                                .catch(function (error) {
                                    console.error(
                                        "Cart update failed:",
                                        error
                                    );

                                    showMessage(
                                        "An unexpected error occurred. Please try again.",
                                        "danger"
                                    );

                                    refreshButtonState();
                                });
                            }
                        );
                    }

                    if (document.readyState === "loading") {
                        document.addEventListener(
                            "DOMContentLoaded",
                            function () {
                                waitForFullCalendar(0);
                            }
                        );
                    } else {
                        waitForFullCalendar(0);
                    }
                }());
